import{_ as e,o,c as s,a2 as r}from"./chunks/framework.1C62pOns.js";const t="/pro-agent-hub-installer/capturas/pt/login.png",n="/pro-agent-hub-installer/capturas/pt/layout.png",i="/pro-agent-hub-installer/capturas/pt/dashboard.png",f=JSON.parse('{"title":"Primeiros passos","description":"","frontmatter":{},"headers":[],"relativePath":"pt/interface/primeiros-passos.md","filePath":"pt/interface/primeiros-passos.md","lastUpdated":1787856241000}'),p={name:"pt/interface/primeiros-passos.md"};function u(m,a,l,d,c,h){return o(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="primeiros-passos" tabindex="-1">Primeiros passos <a class="header-anchor" href="#primeiros-passos" aria-label="Permalink to &quot;Primeiros passos&quot;">​</a></h1><h2 id="entrar" tabindex="-1">Entrar <a class="header-anchor" href="#entrar" aria-label="Permalink to &quot;Entrar&quot;">​</a></h2><p><img src="'+t+'" alt="login"></p><p>O acesso é por e-mail e senha. Se a instalação acabou de subir, o usuário inicial é criado pelo instalador — a senha dele está na saída do <code>install.sh</code>.</p><p><strong>Esqueci a senha</strong> envia um link por e-mail, e por isso só funciona depois que o SMTP estiver configurado em <a href="/pro-agent-hub-installer/pt/interface/administracao#configurações">Configurações</a>. Numa instalação nova, antes disso, a recuperação não tem por onde sair.</p><p><strong>Criar conta</strong> cadastra um usuário sem nenhum grupo. Ele entra, e não vê quase nada — é o comportamento correto: quem dá acesso é um master, ligando o usuário a um grupo.</p><h2 id="o-menu" tabindex="-1">O menu <a class="header-anchor" href="#o-menu" aria-label="Permalink to &quot;O menu&quot;">​</a></h2><p><img src="'+n+'" alt="layout"></p><p>O menu lateral é dividido por assunto: <strong>Principal</strong> (o dia a dia), <strong>Configuração IA</strong> (o que alimenta os agentes), <strong>Integrações</strong> e <strong>Administração</strong>. As três últimas só aparecem para usuários master.</p><p>Ele pode ser recolhido para uma faixa de ícones; passando o mouse, o submenu aparece flutuando. A busca no topo filtra os itens do menu pelo nome — útil quando a instalação tem muitos Apps.</p><p><strong>Os seus Apps aparecem no menu</strong>, logo abaixo de Principal, como itens próprios — não numa tela que os lista. Para quem usa, &quot;Formulário de Pesquisa&quot; é um item do menu como qualquer outro, e não &quot;um App dentro do App Builder&quot;.</p><h2 id="o-painel" tabindex="-1">O painel <a class="header-anchor" href="#o-painel" aria-label="Permalink to &quot;O painel&quot;">​</a></h2><p><img src="'+i+'" alt="dashboard"></p><p>Números de uso e as últimas atividades. É um resumo, não uma ferramenta de operação: para acompanhar execução de workflow em andamento, a tela é <a href="/pro-agent-hub-installer/pt/interface/workflows#execuções">Execuções</a>; para consumo e custo, é <a href="/pro-agent-hub-installer/pt/interface/administracao#consumo-de-tokens">Consumo de tokens</a>.</p><h2 id="tema-e-idioma" tabindex="-1">Tema e idioma <a class="header-anchor" href="#tema-e-idioma" aria-label="Permalink to &quot;Tema e idioma&quot;">​</a></h2><p>No rodapé do menu ficam o seletor de tema (claro/escuro) e o de idioma. A plataforma está em português, inglês e espanhol; a escolha é por usuário e persiste entre sessões.</p>',16)])])}const _=e(p,[["render",u]]);export{f as __pageData,_ as default};
